/**
 * @method
 * @name scwin.calcFixAsset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calcFixAsset = function () {
    /* sdd-asis-lifecycle:begin fn_CalcFixAsset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const invstgClmTpCd = $c.util.getComponent('dma_RegisterReq').get('invstgClmTpCd');

    $c.util.getComponent('ipt_halfFixasstAmt').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_halfInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfTanasstAmt').getValue())
            + scwin.rmComma($c.util.getComponent('ipt_halfIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfMiscFixasstAmt').getValue()) ));

    if(invstgClmTpCd != 5) {
        $c.util.getComponent('ipt_fsttrmFixasstAmt').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_fsttrmInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmTanasstAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_fsttrmIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmMiscFixasstAmt').getValue()) ));

        $c.util.getComponent('ipt_scndtrmFixasstAmt').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_scndtrmInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmTanasstAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_scndtrmIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmMiscFixasstAmt').getValue())));
    }

    fn_CalcAssetSum(); //자산총계

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcCapSum
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calcCapSum = function () {
    /* sdd-asis-lifecycle:begin fn_CalcCapSum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const invstgClmTpCd = $c.util.getComponent('dma_RegisterReq').get('invstgClmTpCd');

    $c.util.getComponent('ipt_halfTotCap').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_halfCap').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfCapSurplus').getValue())
            + scwin.rmComma($c.util.getComponent('ipt_halfProftAmtSurplus').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfCapAdjAmt').getValue())
            + scwin.rmComma($c.util.getComponent('ipt_halfAccOthrCmprIncm').getValue())
    ));

    if(invstgClmTpCd != 5) {
        $c.util.getComponent('ipt_fsttrmTotCap').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_fsttrmCap').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmCapSurplus').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_fsttrmProftAmtSurplus').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmCapAdjAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_fsttrmAccOthrCmprIncm').getValue())
        ));

        $c.util.getComponent('ipt_scndtrmTotCap').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_scndtrmCap').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmCapSurplus').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_scndtrmProftAmtSurplus').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmCapAdjAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_scndtrmAccOthrCmprIncm').getValue())
        ));
    }

    fn_DebtCapSum();//부채와 자본총계

    /* sdd-asis-lifecycle:end */
};


